begin;
select plan(15);

values('10000000-0000-4000-8000-000000000010','Trap matrix','America/Vancouver');
values('10000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000010','Trap room','sky_room');
values('10000000-0000-4000-8000-000000000030','Tiny flag','sticker','common');

set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.apply_room_action('10000000-0000-4000-8000-000000000061','10000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000041','10000000-0000-4000-8000-000000000030','prank')$$,'glue trap resolves');
select is((select result from public.room_actions where entitlement_id='10000000-0000-4000-8000-000000000061'),'trap_triggered','glue trap consumes prank');
select is((select current_item_id from public.room_slots where id='10000000-0000-4000-8000-000000000041'),null,'glue trap prevents mutation');
select lives_ok($$select public.apply_room_action('10000000-0000-4000-8000-000000000062','10000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000042','10000000-0000-4000-8000-000000000030','prank')$$,'mirror trap resolves');
select is((select result from public.room_actions where entitlement_id='10000000-0000-4000-8000-000000000062'),'reflected','mirror trap reflects prank');
select is((select current_item_id from public.room_slots where id='10000000-0000-4000-8000-000000000042'),null,'reflected prank does not mutate target');
select lives_ok($$select public.apply_room_action('10000000-0000-4000-8000-000000000063','10000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000043','10000000-0000-4000-8000-000000000030','prank')$$,'alarm trap resolves');
select is((select result from public.room_actions where entitlement_id='10000000-0000-4000-8000-000000000063'),'applied','alarm reveals but allows prank');
select ok((select (metadata->>'revealed')::boolean from public.room_actions where entitlement_id='10000000-0000-4000-8000-000000000063'),'alarm marks action as revealed');
select lives_ok($$select public.apply_room_action('10000000-0000-4000-8000-000000000064','10000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000044','10000000-0000-4000-8000-000000000030','prank')$$,'decoy trap resolves');
select is((select result from public.room_actions where entitlement_id='10000000-0000-4000-8000-000000000064'),'trap_triggered','decoy redirects prank');
select lives_ok($$select public.apply_room_action('10000000-0000-4000-8000-000000000065','10000000-0000-4000-8000-000000000020','10000000-0000-4000-8000-000000000045','10000000-0000-4000-8000-000000000030','prank')$$,'lock trap resolves');
select is((select result from public.room_actions where entitlement_id='10000000-0000-4000-8000-000000000065'),'trap_triggered','lock trap blocks prank');
select is((select current_item_id from public.room_slots where id='10000000-0000-4000-8000-000000000045'),null,'lock trap prevents mutation');
select is((select count(*) from public.room_traps where status='triggered'),5::bigint,'all triggered traps have authoritative status');

select * from finish();
rollback;
